function pegarValor(e){return Number(document.getElementById(e).value)||0}function calcularGastos(){var e=pegarValor("aluguel")+pegarValor("agua")+pegarValor("luz")+pegarValor("internet")+pegarValor("outros"),a=document.getElementById("resultado");a.innerText="Total mensal: R$ "+e.toFixed(2),a.className=3e3<e?"alerta":"ok"}